begin;
select no_plan();
create temp table channel_ids as select gen_random_uuid() owner,gen_random_uuid() outsider,gen_random_uuid() artist,gen_random_uuid() other_artist,gen_random_uuid() product,gen_random_uuid() unlimited,gen_random_uuid() event1,gen_random_uuid() event2,gen_random_uuid() foreign_event,gen_random_uuid() campaign;
insert into auth.users(id,email) select owner,'channel-owner@example.local' from channel_ids union all select outsider,'channel-outsider@example.local' from channel_ids;
insert into public.artists(id,slug,display_name) select artist,'channel-fixture','Channel fixture' from channel_ids union all select other_artist,'channel-other','Other' from channel_ids;
insert into public.artist_members(artist_id,member_email,role,status) select artist,'channel-owner@example.local','owner','active' from channel_ids;
insert into public.products(id,artist_id,name,price,status,is_unlimited,stock_total,stock_reserved,stock_sold) select product,artist,'Finite',100,'enable',false,20,0,0 from channel_ids union all select unlimited,artist,'Unlimited',100,'enable',true,null,0,0 from channel_ids;
insert into public.events(id,artist_id,event_name,start_date,end_date,status,catalog_initialized_at) select event1,artist,'One',now(),now()+interval '1 day','Confirmed',now() from channel_ids union all select event2,artist,'Two',now(),now()+interval '1 day','Confirmed',now() from channel_ids union all select foreign_event,other_artist,'Other',now(),now()+interval '1 day','Confirmed',now() from channel_ids;
insert into public.online_campaigns(id,artist_id,name,slug,opens_at,closes_at) select campaign,artist,'Campaign','channel-fixture',now(),now()+interval '1 day' from channel_ids;
select set_config('request.jwt.claims',jsonb_build_object('sub',owner,'email','channel-owner@example.local','role','authenticated')::text,true) from channel_ids;
select lives_ok($$select public.save_product_sales_channels((select product from channel_ids),array[(select event1 from channel_ids),(select event2 from channel_ids)],array[(select campaign from channel_ids)])$$,'owner enables multiple events and campaign atomically');
select is((select count(*) from public.event_products where product_id=(select product from channel_ids) and is_enabled and stock_total=0),2::bigint,'both event allocations start at zero');
select is((select stock_total from public.online_campaign_products where product_id=(select product from channel_ids)),0,'campaign starts at zero');
update public.event_products set stock_total=8,stock_reserved=1,stock_sold=2,price_override=75 where event_id=(select event1 from channel_ids) and product_id=(select product from channel_ids);
select lives_ok($$select public.save_product_sales_channels((select product from channel_ids),array[(select event2 from channel_ids)],array[(select campaign from channel_ids)])$$,'unchecking hides only the deselected event');
select ok((select not is_enabled and stock_total=8 and stock_reserved=1 and stock_sold=2 and price_override=75 from public.event_products where event_id=(select event1 from channel_ids) and product_id=(select product from channel_ids)),'hiding preserves allocation holds sales and price');
select lives_ok($$select public.save_product_sales_channels((select product from channel_ids),array[(select event1 from channel_ids),(select event2 from channel_ids)],array[(select campaign from channel_ids)])$$,'rechecking uses the existing allocation');
select is((select stock_total from public.event_products where event_id=(select event1 from channel_ids) and product_id=(select product from channel_ids)),8,'rechecking never resets allocated stock');
select throws_ok($$select public.save_product_sales_channels((select product from channel_ids),array[(select foreign_event from channel_ids)],'{}')$$,'P0001','invalid_channels','foreign channel rejects the entire request');
select ok((select is_enabled from public.event_products where event_id=(select event1 from channel_ids) and product_id=(select product from channel_ids)),'failed request did not hide a valid membership');
select lives_ok($$select public.save_product_sales_channels((select unlimited from channel_ids),array[(select event1 from channel_ids)],array[(select campaign from channel_ids)])$$,'untracked product can use multiple channels');
select ok((select is_unlimited and stock_total is null from public.online_campaign_products where product_id=(select unlimited from channel_ids)),'untracked membership retains unlimited mode');
select set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'email','channel-outsider@example.local','role','authenticated')::text,true) from channel_ids;
select throws_ok($$select public.save_product_sales_channels((select product from channel_ids),'{}','{}')$$,'P0001','forbidden','unrelated user cannot hide memberships');
select ok(not has_function_privilege('anon','public.save_product_sales_channels(uuid,uuid[],uuid[])','execute'),'anonymous role cannot execute membership writes');
select * from finish();
rollback;
